<form method="POST" action="{{ route('admin.label-sheet') }}" id="labelForm">@csrf<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 12px;padding:12px;border:1px solid #e5e7eb;border-radius:12px;background:#f8fafc"><label style="display:flex;align-items:center;gap:8px;font-weight:800;font-size:12px"><input type="checkbox" id="selectAll"> Select all on this page</label><div style="display:flex;align-items:center;gap:8px"><span id="selectedCount" style="font-size:11px;color:#64748b">0 selected</span><button class="button button-dark" type="submit" id="printBtn" disabled>Print Selected Labels</button></div></div><div style="overflow:auto"><table style="width:100%;border-collapse:collapse;min-width:760px"><tr><th></th><th align="left">Product</th><th>Vendor</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th></tr>@foreach($products as $product)<tr style="border-top:1px solid #eef2f7"><td style="padding:12px 4px"><input class="productCheck" type="checkbox" name="ids[]" value="{{ $product->id }}"></td><td style="padding:12px 4px;font-weight:700">{{ $product->name }}</td><td>{{ $product->vendor->business_name ?? '-' }}</td><td>{{ $product->category->name ?? '-' }}</td><td>{{ $product->retail_price }} {{ $product->currency }}</td><td>{{ $product->stock }}</td><td>{{ $product->status }}</td></tr>@endforeach</table></div></form>{{ $products->links() }}<script>const checks=[...document.querySelectorAll('.productCheck')],all=document.getElementById('selectAll'),count=document.getElementById('selectedCount'),btn=document.getElementById('printBtn');function sync(){let n=checks.filter(x=>x.checked).length;count.textContent=n+' selected';btn.disabled=n<1||n>100;all.checked=n===checks.length&&n>0}checks.forEach(x=>x.addEventListener('change',sync));all.addEventListener('change',()=>{checks.forEach(x=>x.checked=all.checked);sync()});</script></div>
